// Triangle meshes for the cross-field tests and renders, all generated by the kernel (no assets).

// The sessions come from the package entry, like examples/feature-bracket whose body this file
// reuses: a Model built against src/ and one built against the package are different classes.
import { type EditMesh, type Model, model, sel } from '@forgeax/engine-modeling';
import { sphere, tessellate, torus } from '@forgeax/engine-modeling/brep';
import type { Result } from '@forgeax/engine-types';
import { lumpySphere } from '../../scripts/quad-eval/cases';
import type { TriMesh } from '../../src/quad/trimesh';
import { buildFeatureBracket } from '../feature-bracket/body';

function must<T, E>(r: Result<T, E>): T {
  if (!r.ok) throw new Error(`fixture failed: ${JSON.stringify(r.error)}`);
  return r.value;
}

/** Fan triangulation of each face loop (valid for the convex loops these fixtures produce). */
export function fanTriangles(
  positions: readonly (readonly number[])[],
  loops: Iterable<readonly number[]>,
): TriMesh {
  const triangles: number[] = [];
  for (const loop of loops)
    for (let k = 1; k + 1 < loop.length; k++)
      triangles.push(loop[0] as number, loop[k] as number, loop[k + 1] as number);
  return { positions: new Float64Array(positions.flat()), triangles: new Uint32Array(triangles) };
}

function editToTri(mesh: EditMesh): TriMesh {
  const ids = new Map<number, number>();
  const positions: number[][] = [];
  const loops: number[][] = [];
  for (const f of mesh.faces())
    loops.push(
      mesh.faceVertices(f).map((v) => {
        let i = ids.get(v);
        if (i === undefined) {
          i = ids.size;
          ids.set(v, i);
          positions.push([...mesh.position(v)]);
        }
        return i;
      }),
    );
  return fanTriangles(positions, loops);
}

function modelToTri(m: Model): TriMesh {
  m.triangulate(sel.all());
  if (m.poisoned !== undefined) throw new Error(`fixture model failed: ${m.poisoned.message}`);
  return editToTri(m.editMesh);
}

export function brepSphere(angle = Math.PI / 12): TriMesh {
  return editToTri(must(tessellate(must(sphere({ radius: 0.5 })), { angle })));
}

export function brepTorus(angle = Math.PI / 12): TriMesh {
  return editToTri(must(tessellate(must(torus({ major: 1, minor: 0.3 })), { angle })));
}

export function lumpy(): TriMesh {
  const m = lumpySphere(32, 16, 7);
  return fanTriangles(m.positions, m.faces);
}

/** A subdivided box with every edge chamfered (one bevel segment). */
export function chamferBox(): TriMesh {
  const m = model();
  m.box({ size: [1, 0.8, 0.6], segments: [6, 5, 4] });
  m.bevel(sel.edges.dihedral('>', 45), { width: 0.08, segments: 1 });
  return modelToTri(m);
}

export function bracket(): TriMesh {
  return modelToTri(buildFeatureBracket());
}

/** A pipe tee: a vertical run with a flange at each end and a horizontal branch, joined by mesh unions. */
export function flangedTee(): TriMesh {
  const m = model();
  const pipe = (label: string, radius: number, height: number, center: [number, number, number]) =>
    m.cylinder({
      radiusTop: radius,
      radiusBottom: radius,
      height,
      radialSegments: 24,
      center,
      label,
    });
  pipe('run', 0.3, 2, [0, 0, 0]);
  pipe('top', 0.5, 0.12, [0, 0.94, 0]);
  m.union(sel.createdBy('top'), { label: 'run-top' });
  pipe('bottom', 0.5, 0.12, [0, -0.94, 0]);
  m.union(sel.createdBy('bottom'), { label: 'run-bottom' });
  pipe('branch', 0.22, 0.9, [0, 0, 0]);
  m.rotate(sel.createdBy('branch'), 'z', 90, [0, 0, 0]);
  m.translate(sel.createdBy('branch'), [0.55, 0, 0]);
  m.union(sel.createdBy('branch'), { label: 'tee' });
  return modelToTri(m);
}

/** A box with one cylindrical boss unioned onto its top face (housing-like body). */
export function bossBox(): TriMesh {
  const m = model();
  m.box({ size: [1, 0.8, 0.8], segments: [4, 4, 4], label: 'body' });
  m.cylinder({
    radiusTop: 0.22,
    radiusBottom: 0.22,
    height: 0.4,
    radialSegments: 16,
    center: [0, 0.6, 0],
    label: 'boss',
  });
  m.union(sel.createdBy('boss'), { label: 'housing' });
  return modelToTri(m);
}

/** A box with a boss and a through-bore (holed top face), built on the mesh path like flangedTee. */
export function housingBody(): TriMesh {
  const m = model();
  m.box({ size: [1, 0.8, 0.8], segments: [4, 4, 4], label: 'body' });
  m.cylinder({ radiusTop: 0.3, radiusBottom: 0.3, height: 0.4, radialSegments: 16, center: [0, 0.6, 0], label: 'boss' });
  m.union(sel.createdBy('boss'), { label: 'housing' });
  m.cylinder({ radiusTop: 0.15, radiusBottom: 0.15, height: 2, radialSegments: 16, center: [0, 0, 0], label: 'bore' });
  m.difference(sel.createdBy('bore'), { label: 'housing-bore' });
  return modelToTri(m);
}
